<?php
declare(strict_types=1);
namespace App\Services;
use App\Config\Database;
use App\Support\Reference;
use PDO;
use RuntimeException;

final class AssignmentService
{
 private static function requireOperations(string$p):void{if(!Auth::hasRole('MCCOLLIN_OPERATIONS')||!Auth::can($p))throw new RuntimeException('Operations assignment permission is required.');}
 private static function operationsRoleId():int{foreach(Auth::context()['roles']??[]as$r)if($r['role_code']==='MCCOLLIN_OPERATIONS')return(int)$r['user_role_id'];throw new RuntimeException('Operations role is required.');}
 private static function carrierContext():array{if(!Auth::hasRole('TRUCK_OWNER')||!Auth::can('ASSIGNMENT_VIEW_OWN'))throw new RuntimeException('Carrier assignment access is required.');$uid=(int)Auth::user()['id'];$p=CarrierOnboarding::current($uid);if(!$p||$p['verification_status']!=='verified'||$p['case_status']!=='approved')throw new RuntimeException('Verified Carrier access is required.');return['company_id'=>$p['owner_type']==='company'?(int)$p['subject_id']:null,'user_id'=>$p['owner_type']==='individual'?$uid:null];}
 public static function queue():array{self::requireOperations('ASSIGNMENT_QUEUE_VIEW');$sql="SELECT o.offer_id,o.offer_ref,o.offer_thread_ref,o.version_no,o.load_id,o.match_id,o.truck_id,o.driver_id,o.carrier_company_id,o.carrier_user_id,o.offered_amount_tzs,o.offered_amount_usd,o.responded_at,l.load_ref,l.cargo_summary,oa.city origin_city,da.city destination_city,t.registration_number,du.display_name driver_name,cc.display_name carrier_company_name,cu.display_name carrier_user_name FROM bids_offers o JOIN loads l ON l.load_id=o.load_id JOIN addresses oa ON oa.address_id=l.origin_address_id JOIN addresses da ON da.address_id=l.destination_address_id JOIN trucks t ON t.truck_id=o.truck_id JOIN drivers d ON d.driver_id=o.driver_id JOIN users du ON du.user_id=d.user_id LEFT JOIN companies cc ON cc.company_id=o.carrier_company_id LEFT JOIN users cu ON cu.user_id=o.carrier_user_id LEFT JOIN assignments a ON a.accepted_offer_id=o.offer_id WHERE o.offer_status='accepted' AND o.status='active' AND a.assignment_id IS NULL ORDER BY o.responded_at";return Database::connection()->query($sql)->fetchAll();}
 public static function all():array{self::requireOperations('ASSIGNMENT_VIEW_ALL');return Database::connection()->query(self::detailSql()." ORDER BY a.assigned_at DESC")->fetchAll();}
 public static function find(int$id):?array{self::requireOperations('ASSIGNMENT_VIEW_ALL');$st=Database::connection()->prepare(self::detailSql()." WHERE a.assignment_id=? LIMIT 1");$st->execute([$id]);$r=$st->fetch();return$r?:null;}
 public static function assign(int$offerId,int$userId,string$note):int
 {self::requireOperations('ASSIGNMENT_CREATE');if($userId!==(int)Auth::user()['id'])throw new RuntimeException('Invalid Operations actor.');$note=trim($note);if(strlen($note)>2000)throw new RuntimeException('Assignment note cannot exceed 2000 characters.');$pdo=Database::connection();$pdo->beginTransaction();try{$sql="SELECT o.*,l.current_status,l.customer_company_id,d.user_id driver_user,ra.availability_status resource_status,t.availability_status truck_status,d.availability_status driver_status FROM bids_offers o JOIN loads l ON l.load_id=o.load_id JOIN resource_availability ra ON ra.truck_id=o.truck_id AND ra.driver_id=o.driver_id JOIN trucks t ON t.truck_id=o.truck_id JOIN drivers d ON d.driver_id=o.driver_id WHERE o.offer_id=? AND o.status='active' FOR UPDATE";$st=$pdo->prepare($sql);$st->execute([$offerId]);$o=$st->fetch();if(!$o||$o['offer_status']!=='accepted')throw new RuntimeException('Only the accepted winning offer may be assigned.');if($o['current_status']!=='approved')throw new RuntimeException('Only an approved load may be assigned.');if($o['resource_status']!=='reserved'||$o['truck_status']!=='reserved'||$o['driver_status']!=='reserved')throw new RuntimeException('The accepted Driver–truck pair must remain reserved.');$st=$pdo->prepare("SELECT COUNT(*) FROM assignments WHERE load_id=? OR accepted_offer_id=?");$st->execute([$o['load_id'],$offerId]);if((int)$st->fetchColumn()>0)throw new RuntimeException('This load or offer is already assigned.');$ref=Reference::make('ASN');$pdo->prepare("INSERT INTO assignments(assignment_ref,load_id,match_id,accepted_offer_id,carrier_company_id,carrier_user_id,truck_id,driver_id,assigned_at,assignment_status,assigned_by_user_id,assignment_note,status,created_by_user_id,updated_by_user_id) VALUES(?,?,?,?,?,?,?,?,UTC_TIMESTAMP(6),'assigned',?,?,'active',?,?)")->execute([$ref,$o['load_id'],$o['match_id'],$offerId,$o['carrier_company_id'],$o['carrier_user_id'],$o['truck_id'],$o['driver_id'],$userId,$note!==''?$note:null,$userId,$userId]);$id=(int)$pdo->lastInsertId();$st=$pdo->prepare("UPDATE loads SET current_status='assigned',updated_by_user_id=?,row_version=row_version+1 WHERE load_id=? AND current_status='approved'");$st->execute([$userId,$o['load_id']]);if($st->rowCount()!==1)throw new RuntimeException('Load assignment state changed.');$pdo->prepare("UPDATE resource_availability SET reason=?,updated_by_user_id=?,row_version=row_version+1 WHERE truck_id=? AND driver_id=? AND availability_status='reserved'")->execute(['Assigned under '.$ref.'; awaiting Phase 8 dispatch',$userId,$o['truck_id'],$o['driver_id']]);$role=self::operationsRoleId();self::history($pdo,'assignment',$id,null,'assigned',$userId,$role,'Operations created assignment from accepted offer '.$o['offer_ref']);self::history($pdo,'load',(int)$o['load_id'],'approved','assigned',$userId,$role,'Transport assigned under '.$ref);self::audit($pdo,'ASSIGNMENT_CREATED',$id,$userId,['assignment_ref'=>$ref,'load_id'=>(int)$o['load_id'],'accepted_offer_id'=>$offerId,'match_id'=>(int)$o['match_id'],'truck_id'=>(int)$o['truck_id'],'driver_id'=>(int)$o['driver_id']]);$notify=[(int)$o['driver_user']];if($o['carrier_user_id'])$notify[]=(int)$o['carrier_user_id'];if($o['carrier_company_id'])$notify=array_merge($notify,NotificationService::usersForCompany($pdo,(int)$o['carrier_company_id']));$notify=array_merge($notify,NotificationService::usersForCompany($pdo,(int)$o['customer_company_id']));NotificationService::send($pdo,$notify,'assignment','Transport assigned','Assignment '.$ref.' has been created for the approved load.',null,'assignment',$id,$userId,'high');$pdo->commit();return$id;}catch(\Throwable$e){if($pdo->inTransaction())$pdo->rollBack();throw$e;}}
 public static function own():array{$c=self::carrierContext();$col=$c['company_id']?'a.carrier_company_id':'a.carrier_user_id';$val=$c['company_id']?:$c['user_id'];$st=Database::connection()->prepare(self::detailSql()." WHERE {$col}=? ORDER BY a.assigned_at DESC");$st->execute([$val]);return$st->fetchAll();}
 private static function detailSql():string{return"SELECT a.*,o.offer_ref,o.offer_thread_ref,o.offered_amount_tzs,o.offered_amount_usd,l.load_ref,l.cargo_summary,oa.city origin_city,da.city destination_city,t.registration_number,t.make_name,t.model_name,du.display_name driver_name,cc.display_name carrier_company_name,cu.display_name carrier_user_name FROM assignments a JOIN bids_offers o ON o.offer_id=a.accepted_offer_id JOIN loads l ON l.load_id=a.load_id JOIN addresses oa ON oa.address_id=l.origin_address_id JOIN addresses da ON da.address_id=l.destination_address_id JOIN trucks t ON t.truck_id=a.truck_id JOIN drivers d ON d.driver_id=a.driver_id JOIN users du ON du.user_id=d.user_id LEFT JOIN companies cc ON cc.company_id=a.carrier_company_id LEFT JOIN users cu ON cu.user_id=a.carrier_user_id";}
 private static function history(PDO$pdo,string$type,int$id,?string$old,string$new,int$uid,int$role,string$reason):void{$pdo->prepare("INSERT INTO status_history(status_history_ref,entity_type,entity_id_value,previous_status,new_status,actor_user_id,actor_user_role_id,source_channel,reason,occurred_at,status,created_by_user_id) VALUES(?,?,?,?,?,?,?,'web',?,UTC_TIMESTAMP(6),'active',?)")->execute([Reference::make('STH'),$type,$id,$old,$new,$uid,$role,$reason,$uid]);}
 private static function audit(PDO$pdo,string$action,int$id,int$uid,array$extra):void{$m=json_encode(array_merge(['action_code'=>$action,'entity_type'=>'assignment','entity_id'=>$id,'source'=>'web'],$extra),JSON_THROW_ON_ERROR);$pdo->prepare("INSERT INTO audit_events(audit_event_ref,metadata_json,status,created_by_user_id) VALUES(?,?,'active',?)")->execute([Reference::make('AUD'),$m,$uid]);}
}
